-- Detail des matchs 2014 importe de Leaguepedia (https://lol.fandom.com, CC BY-SA 3.0) par
-- import/import_games.py : NE PAS EDITER A LA MAIN, regenerer le fichier.
-- Scores des series sans score, manches (vainqueur, MVP, champions, K/D/A, bans) des series
-- sans manche, joueurs relies a Leaguepedia (pseudo actuel, nationalite, poste, passages).
-- Les verifications 'ERREUR import Leaguepedia' arretent la migration si la base ne
-- correspond pas a celle d'ou le fichier a ete genere.

CREATE TEMP TABLE lp_team (id BIGINT PRIMARY KEY, name TEXT NOT NULL);
SELECT ('ERREUR import Leaguepedia : equipe introuvable ' || c.ok::text)::int FROM (SELECT ((SELECT count(*) FROM lp_team l JOIN team t ON t.id = l.id AND t.name = l.name) = (SELECT count(*) FROM lp_team)) AS ok) c WHERE NOT c.ok;

-- Joueurs : relies a leur page Leaguepedia (fiche existante, doublons fusionnes) ou crees.
CREATE TEMP TABLE lp_player (source_key TEXT PRIMARY KEY, pseudo TEXT NOT NULL, nationality TEXT, position TEXT NOT NULL, existing_id BIGINT, existing_pseudo TEXT);
SELECT ('ERREUR import Leaguepedia : joueur existant introuvable ' || c.ok::text)::int FROM (SELECT ((SELECT count(*) FROM lp_player l JOIN player p ON p.id = l.existing_id AND p.pseudo = l.existing_pseudo AND p.source_key IS NULL) = (SELECT count(*) FROM lp_player WHERE existing_id IS NOT NULL)) AS ok) c WHERE NOT c.ok;

-- Doublons : manches, MVP et passages passent sur la fiche gardee, le doublon est supprime.
CREATE TEMP TABLE lp_merge (dup_id BIGINT PRIMARY KEY, dup_pseudo TEXT NOT NULL, keep_id BIGINT NOT NULL);
SELECT ('ERREUR import Leaguepedia : doublon introuvable ' || c.ok::text)::int FROM (SELECT ((SELECT count(*) FROM lp_merge m JOIN player p ON p.id = m.dup_id AND p.pseudo = m.dup_pseudo) = (SELECT count(*) FROM lp_merge)) AS ok) c WHERE NOT c.ok;
UPDATE match_game_player gp SET player_id = m.keep_id FROM lp_merge m WHERE gp.player_id = m.dup_id;
UPDATE match_game g SET mvp_player_id = m.keep_id FROM lp_merge m WHERE g.mvp_player_id = m.dup_id;
UPDATE match x SET mvp_player_id = m.keep_id FROM lp_merge m WHERE x.mvp_player_id = m.dup_id;
DELETE FROM player_stint s USING lp_merge m WHERE s.player_id = m.dup_id;
DELETE FROM player p USING lp_merge m WHERE p.id = m.dup_id;
DROP TABLE lp_merge;

UPDATE player p SET source_key = l.source_key FROM lp_player l WHERE p.id = l.existing_id;
UPDATE player p SET pseudo = l.pseudo, nationality = l.nationality, position = l.position FROM lp_player l WHERE p.source_key = l.source_key;

-- Passages : toute la carriere d'apres les contrats Leaguepedia (remplace les passages saisis).
DELETE FROM player_stint s USING lp_player l, player p WHERE p.source_key = l.source_key AND s.player_id = p.id;
CREATE TEMP TABLE lp_stint (source_key TEXT NOT NULL, team_id BIGINT NOT NULL, position TEXT NOT NULL, start_date DATE NOT NULL, end_date DATE);
DROP TABLE lp_stint;
-- Equipe actuelle = celle du passage en cours (aucune pour un joueur sans contrat).
UPDATE player p SET team_id = (SELECT s.team_id FROM player_stint s WHERE s.player_id = p.id AND s.end_date IS NULL) FROM lp_player l WHERE p.source_key = l.source_key;

-- Series : retrouvees par competition, date et heure (verification), puis completees.
CREATE TEMP TABLE lp_series (match_id BIGINT PRIMARY KEY, source_key TEXT NOT NULL, date DATE NOT NULL, time TIME, team1_id BIGINT, team2_id BIGINT, score1 INT, score2 INT, mvp TEXT);
SELECT ('ERREUR import Leaguepedia : match introuvable ' || c.ok::text)::int FROM (SELECT ((SELECT count(*) FROM lp_series s JOIN match m ON m.id = s.match_id AND m.date = s.date AND m.time IS NOT DISTINCT FROM s.time JOIN competition c ON c.id = m.competition_id AND c.source_key = s.source_key) = (SELECT count(*) FROM lp_series)) AS ok) c WHERE NOT c.ok;
UPDATE match m SET team1_id = coalesce(m.team1_id, s.team1_id), team2_id = coalesce(m.team2_id, s.team2_id), score1 = s.score1, score2 = s.score2, status = 'COMPLETED' FROM lp_series s WHERE m.id = s.match_id AND m.score1 IS NULL AND s.score1 IS NOT NULL;
UPDATE match m SET team1_id = coalesce(m.team1_id, s.team1_id), team2_id = coalesce(m.team2_id, s.team2_id) FROM lp_series s WHERE m.id = s.match_id AND (m.team1_id IS NULL OR m.team2_id IS NULL);
UPDATE match m SET mvp_player_id = p.id FROM lp_series s JOIN player p ON p.source_key = s.mvp WHERE m.id = s.match_id AND m.mvp_player_id IS NULL;

-- Manches : creees si absentes ; vainqueur et MVP completes s'ils manquent.
CREATE TEMP TABLE lp_game (match_id BIGINT NOT NULL, game_number INT NOT NULL, winner_team_id BIGINT, mvp TEXT, PRIMARY KEY (match_id, game_number));
UPDATE match_game x SET winner_team_id = coalesce(x.winner_team_id, g.winner_team_id), mvp_player_id = coalesce(x.mvp_player_id, p.id) FROM lp_game g LEFT JOIN player p ON p.source_key = g.mvp WHERE x.match_id = g.match_id AND x.game_number = g.game_number;
DROP TABLE lp_game;

-- Champions et K/D/A, pour les manches qui n'en ont pas encore.
CREATE TEMP TABLE lp_game_player (match_id BIGINT NOT NULL, game_number INT NOT NULL, player TEXT NOT NULL, team_id BIGINT NOT NULL, position TEXT NOT NULL, champion TEXT NOT NULL, kills INT, deaths INT, assists INT);
SELECT ('ERREUR import Leaguepedia : ligne joueur non importee ' || c.ok::text)::int FROM (SELECT ((SELECT count(*) FROM lp_game_player l JOIN match_game x ON x.match_id = l.match_id AND x.game_number = l.game_number JOIN player p ON p.source_key = l.player JOIN match_game_player y ON y.game_id = x.id AND y.player_id = p.id) = (SELECT count(*) FROM lp_game_player)) AS ok) c WHERE NOT c.ok;
DROP TABLE lp_game_player;

-- Bans, pour les manches qui n'en ont pas encore.
CREATE TEMP TABLE lp_ban (match_id BIGINT NOT NULL, game_number INT NOT NULL, team_id BIGINT NOT NULL, champion TEXT NOT NULL);
DROP TABLE lp_ban;

DROP TABLE lp_series;
DROP TABLE lp_team;
DROP TABLE lp_player;
